-- SecondBrain pgvector foundation schema
create extension if not exists vector;
create schema if not exists secondbrain;

create table if not exists secondbrain.p1_documents (
    id text primary key,
    source text not null,
    title text not null,
    content_hash text not null,
    created_at timestamptz not null,
    metadata_json jsonb not null default '{}'::jsonb
);

create table if not exists secondbrain.p1_chunks (
    id text primary key,
    document_id text not null references secondbrain.p1_documents(id) on delete cascade,
    ordinal integer not null,
    text text not null,
    char_start integer not null default 0,
    char_end integer not null default 0,
    token_json jsonb not null default '[]'::jsonb,
    token_count integer not null default 0,
    created_at timestamptz not null
);

create table if not exists secondbrain.p1_chunk_embeddings (
    chunk_id text primary key references secondbrain.p1_chunks(id) on delete cascade,
    provider text not null,
    dimensions integer not null,
    embedding vector(1536) not null,
    created_at timestamptz not null
);

create index if not exists idx_p1_documents_source on secondbrain.p1_documents(source);
create index if not exists idx_p1_chunks_document on secondbrain.p1_chunks(document_id);
create index if not exists idx_p1_embeddings_provider on secondbrain.p1_chunk_embeddings(provider);
create index if not exists idx_p1_embeddings_vector on secondbrain.p1_chunk_embeddings using ivfflat (embedding vector_cosine_ops);

